#include <stdio.h>
int square(int x) {
    return x * x;
}
int main(void) {
    int n = 5;
    printf("%d\n", square(n));
    return 0;
}

#include <stdio.h>
void increment(int x) {
    x = x + 1;
}
int main(void) {
    int n = 5;
    increment(n);
    printf("%d\n", n);
    return 0;
}

#include <stdio.h>
int classify(int n) {
    if (n > 0) {
        return 1;
    }
    if (n < 0) {
        return -1;
    }
    return 0;
}
int main(void) {
    printf("%d %d %d\n", classify(5), classify(-3), classify(0));
    return 0;
}

#include <stdio.h>
int counter(void) {
    int x = 0;
    x++;
    return x;
}
int main(void) {
    printf("%d\n", counter() + counter() + counter());
    return 0;
}

#include <stdio.h>
int double_it(int x) {
    return x * 2;
}
int add_one(int x) {
    return x + 1;
}
int main(void) {
    printf("%d\n", add_one(double_it(5)));
    return 0;
}

#include <stdio.h>
double half(int x) {
    return x / 2.0;
}
int main(void) {
    printf("%.2f\n", half(7));
    return 0;
}

#include <stdio.h>
int next_id(void) {
    static int id = 100;
    return id++;
}
int main(void) {
    printf("%d ", next_id());
    printf("%d ", next_id());
    printf("%d\n", next_id());
    return 0;
}

#include <stdio.h>
int add(int a, int b) {
    return a + b;
}
int main(void) {
    int r1 = add(1, 2);
    int r2 = add(r1, 3);
    int r3 = add(r2, 4);
    printf("%d\n", r3);
    return 0;
}

#include <stdio.h>
int total = 0;
void add_to_total(int x) {
    total += x;
}
int main(void) {
    add_to_total(5);
    add_to_total(10);
    add_to_total(15);
    printf("%d\n", total);
    return 0;
}

#include <stdio.h>
int is_even(int n) {
    return n % 2 == 0;
}
int main(void) {
    printf("%d %d %d\n", is_even(4), is_even(7), is_even(0));
    return 0;
}
